#include "pattern_brush_library.h"
#include <algorithm>
#include <chrono>
#include <fstream>
#include <set>
#include <tuple>
#include <windows.h>
#include <regex>
namespace moon {namespace {
constexpr const char* orderFile=".brush-order.json";
void atomicBytes(const std::filesystem::path& p,const std::vector<std::uint8_t>& b){auto t=p;t+=L".tmp";{std::ofstream f(t,std::ios::binary|std::ios::trunc);if(!f)throw std::runtime_error("Cannot write brush file");f.write((const char*)b.data(),std::streamsize(b.size()));if(!f)throw std::runtime_error("Cannot write brush file");}std::error_code e;if(!MoveFileExW(t.c_str(),p.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)){std::filesystem::remove(t);throw std::runtime_error("Cannot replace brush file");}}
std::filesystem::path pathFor(const std::filesystem::path& d,const std::string& id){if(!PatternBrushLibrary::safeId(id))throw std::invalid_argument("Invalid brush file ID");for(auto& e:std::filesystem::recursive_directory_iterator(d))if((GetFileAttributesW(e.path().c_str())&FILE_ATTRIBUTE_REPARSE_POINT)!=0)throw std::runtime_error("Linked brush paths are not supported");else if(e.is_regular_file()&&e.path().filename().u8string()==id)return e.path();throw std::runtime_error("Brush file does not exist");}
std::string folderName(std::string value){std::string result;for(unsigned char c:value)if(std::string("/\\:*?\"<>|").find(char(c))==std::string::npos)result+=char(c);auto a=result.find_first_not_of(" \t\r\n"),b=result.find_last_not_of(" \t\r\n");if(a==std::string::npos)throw std::invalid_argument("Brush folder name cannot be empty");result=result.substr(a,b-a+1);if(result=="."||result.find("..")!=std::string::npos||result.back()=='.')throw std::invalid_argument("Invalid brush folder name");return result;}
std::filesystem::path folderPath(const std::filesystem::path& root,const std::string& id,bool allowRoot=false){
 if(id.empty()){if(allowRoot)return root;throw std::invalid_argument("Folder ID cannot be empty");}
 if(id.find("..")!=std::string::npos||id.front()=='/'||id.front()=='\\')throw std::invalid_argument("Invalid brush folder ID");
 auto path=root;std::size_t start=0;while(start<id.size()){auto end=id.find('/',start);auto part=id.substr(start,end==std::string::npos?std::string::npos:end-start);if(part.empty()||part=="."||part.find_first_of("\\:*?\"<>|")!=std::string::npos)throw std::invalid_argument("Invalid brush folder ID");path/=std::filesystem::u8path(part);auto attributes=GetFileAttributesW(path.c_str());if(attributes!=INVALID_FILE_ATTRIBUTES&&(attributes&FILE_ATTRIBUTE_REPARSE_POINT))throw std::invalid_argument("Linked brush folders are not supported");if(end==std::string::npos)break;start=end+1;if(start==id.size())throw std::invalid_argument("Invalid brush folder ID");}
 auto base=std::filesystem::weakly_canonical(root),resolved=std::filesystem::weakly_canonical(path);auto relative=resolved.lexically_relative(base);if(relative.empty()||relative==L"."||*relative.begin()==L"..")throw std::invalid_argument("Brush folder is outside library");return path;
}
StoredPatternBrushFolder describeFolder(const std::filesystem::path& root,const std::filesystem::path& path){return {path.lexically_relative(root).generic_u8string(),path.filename().u8string(),path.u8string()};}

}
PatternBrushLibrary::PatternBrushLibrary(std::filesystem::path d):directory_(std::move(d)){std::filesystem::create_directories(directory_);if(!std::filesystem::is_directory(directory_))throw std::runtime_error("Brush path is not a directory");}
std::string PatternBrushLibrary::cleanName(const std::string& n){std::string r;for(char c:n)if(std::string("/\\:*?\"<>|").find(c)==std::string::npos)r.push_back(c);auto a=r.find_first_not_of(" \t\r\n"),b=r.find_last_not_of(" \t\r\n");return a==std::string::npos?"选区笔刷":r.substr(a,b-a+1);}
bool PatternBrushLibrary::safeId(const std::string& id){return id.size()>4&&id.substr(id.size()-4)==".png"&&id.find("..") == std::string::npos&&id.find('/')==std::string::npos&&id.find('\\')==std::string::npos;}
std::string quoteJson(const std::string& value){std::string r="\"";for(unsigned char c:value){if(c=='"'||c=='\\')r+='\\';if(c<32)throw std::invalid_argument("Invalid control character in brush name");r+=char(c);}return r+"\"";}
std::vector<std::string> PatternBrushLibrary::readOrder()const{std::ifstream f(directory_/orderFile);std::string text((std::istreambuf_iterator<char>(f)),{});std::vector<std::string> result;auto i=text.find('[');if(i==std::string::npos)return {};for(++i;i<text.size();){while(i<text.size()&&(isspace((unsigned char)text[i])||text[i]==','))++i;if(i==text.size()||text[i]==']')break;if(text[i++]!='"')return {};std::string id;bool closed=false;while(i<text.size()){char c=text[i++];if(c=='"'){closed=true;break;}if(c=='\\'){if(i==text.size())return {};c=text[i++];if(c!='"'&&c!='\\'&&c!='/')return {};}id+=c;}if(!closed)return {};if(safeId(id))result.push_back(id);}return result;}
void PatternBrushLibrary::writeOrder(const std::vector<std::string>& ids)const{std::string text="[";for(auto& id:ids){if(text.size()>1)text+=',';text+=quoteJson(id);}text+=']';atomicBytes(directory_/orderFile,{text.begin(),text.end()});}
PatternBrushListing PatternBrushLibrary::list()const{PatternBrushListing r{directory_,{}};for(auto& e:std::filesystem::recursive_directory_iterator(directory_))if((GetFileAttributesW(e.path().c_str())&FILE_ATTRIBUTE_REPARSE_POINT)!=0)throw std::runtime_error("Linked brush paths are not supported");else if(e.is_directory()){auto relative=e.path().lexically_relative(directory_).generic_u8string();r.folders.push_back({relative,e.path().filename().u8string(),e.path().u8string()});}else if(e.is_regular_file()&&e.path().extension()==L".png"){auto id=e.path().filename().u8string();if(!safeId(id))continue;StoredPatternBrush item{id,e.path().stem().u8string(),e.path().u8string(),true,{},{}};auto meta=e.path();meta.replace_extension(L".meta.json");std::ifstream f(meta);std::string text((std::istreambuf_iterator<char>(f)),{});for(auto key:{"sourceX","sourceY"}){std::smatch match;std::regex pattern(std::string("\"")+key+"\"[[:space:]]*:[[:space:]]*(-?[0-9]+)");if(std::regex_search(text,match,pattern)){try{auto value=std::stoi(match[1]);(std::string(key)=="sourceX"?item.sourceX:item.sourceY)=value;}catch(...){}}}item.folderId=e.path().parent_path().lexically_relative(directory_).generic_u8string();if(item.folderId==".")item.folderId.clear();r.brushes.push_back(std::move(item));}std::sort(r.folders.begin(),r.folders.end(),[](auto&a,auto&b){return a.id<b.id;});auto o=readOrder();std::stable_sort(r.brushes.begin(),r.brushes.end(),[&](auto&a,auto&b){auto ia=std::find(o.begin(),o.end(),a.id),ib=std::find(o.begin(),o.end(),b.id);return std::tuple(ia==o.end(),ia==o.end()?0:ia-o.begin(),a.name,a.id)<std::tuple(ib==o.end(),ib==o.end()?0:ib-o.begin(),b.name,b.id);});return r;}
StoredPatternBrush PatternBrushLibrary::save(std::string n,const std::vector<std::uint8_t>& png,bool intrinsic,std::optional<int> x,std::optional<int> y){n=cleanName(n);if(png.size()<8||png[0]!=137||png[1]!=80||png[2]!=78||png[3]!=71)throw std::invalid_argument("Invalid brush PNG payload");auto id=n+"-"+std::to_string(std::chrono::high_resolution_clock::now().time_since_epoch().count())+".png";auto path=directory_/std::filesystem::u8path(id);auto meta=path;meta.replace_extension(L".meta.json");auto order=readOrder();atomicBytes(path,png);try{std::string metadata=std::string("{\"intrinsicSize\":")+(intrinsic?"true":"false")+",\"sourceX\":"+(x?std::to_string(*x):"null")+",\"sourceY\":"+(y?std::to_string(*y):"null")+"}";atomicBytes(meta,{metadata.begin(),metadata.end()});order.push_back(id);writeOrder(order);}catch(...){std::error_code e;std::filesystem::remove(path,e);std::filesystem::remove(meta,e);throw;}return{id,path.stem().u8string(),path.u8string(),true,x,y};}
void PatternBrushLibrary::remove(const std::string& id){auto p=pathFor(directory_,id);auto previous=readOrder();auto o=previous;o.erase(std::remove(o.begin(),o.end(),id),o.end());writeOrder(o);std::error_code e;if(!std::filesystem::remove(p,e)||e){writeOrder(previous);throw std::runtime_error("Cannot delete brush file");}p.replace_extension(L".meta.json");std::filesystem::remove(p,e);}
void PatternBrushLibrary::reorder(const std::vector<std::string>& ids){std::set<std::string> v;for(auto& x:list().brushes)v.insert(x.id);std::vector<std::string> o;for(auto& x:ids)if(v.erase(x))o.push_back(x);for(auto& x:v)o.push_back(x);writeOrder(o);}
StoredPatternBrushFolder PatternBrushLibrary::createFolder(std::string name,const std::string& parent){auto path=folderPath(directory_,parent,true);if(!std::filesystem::is_directory(path))throw std::runtime_error("Parent brush folder does not exist");name=folderName(name);auto base=name;int suffix=2;while(std::filesystem::exists(path/std::filesystem::u8path(name)))name=base+"-"+std::to_string(suffix++);path/=std::filesystem::u8path(name);std::filesystem::create_directory(path);return describeFolder(directory_,path);}
StoredPatternBrushFolder PatternBrushLibrary::renameFolder(const std::string& id,std::string name){auto source=folderPath(directory_,id);if(!std::filesystem::is_directory(source))throw std::runtime_error("Brush folder does not exist");name=folderName(name);auto target=source.parent_path()/std::filesystem::u8path(name);if(source==target)return describeFolder(directory_,source);if(std::filesystem::exists(target)){if(!std::filesystem::equivalent(source,target))throw std::runtime_error("Brush folder name already exists");auto temp=source.parent_path()/(L".moonsprite-folder-"+std::to_wstring(std::chrono::high_resolution_clock::now().time_since_epoch().count()));std::filesystem::rename(source,temp);try{std::filesystem::rename(temp,target);}catch(...){std::filesystem::rename(temp,source);throw;}}else std::filesystem::rename(source,target);return describeFolder(directory_,target);}
StoredPatternBrush PatternBrushLibrary::move(const std::string& id,const std::string& folder){auto source=pathFor(directory_,id),destination=folderPath(directory_,folder,true);if(!std::filesystem::is_directory(destination))throw std::runtime_error("Brush folder does not exist");auto target=destination/source.filename();if(source!=target){if(std::filesystem::exists(target))throw std::runtime_error("Brush already exists in target folder");auto oldMeta=source,newMeta=target;oldMeta.replace_extension(L".meta.json");newMeta.replace_extension(L".meta.json");std::filesystem::rename(source,target);try{if(std::filesystem::exists(oldMeta)){if(std::filesystem::exists(newMeta))throw std::runtime_error("Target brush metadata already exists");std::filesystem::rename(oldMeta,newMeta);}}catch(...){std::filesystem::rename(target,source);throw;}}for(auto& item:list().brushes)if(item.id==id)return item;throw std::runtime_error("Moved brush missing from library");}
void PatternBrushLibrary::removeFolder(const std::string& id){auto target=folderPath(directory_,id);if(!std::filesystem::is_directory(target))throw std::runtime_error("Brush folder does not exist");std::set<std::string> deleted;for(auto& entry:std::filesystem::recursive_directory_iterator(target)){auto attributes=GetFileAttributesW(entry.path().c_str());if(attributes!=INVALID_FILE_ATTRIBUTES&&(attributes&FILE_ATTRIBUTE_REPARSE_POINT))throw std::invalid_argument("Linked brush folder content is not supported");if(entry.is_regular_file()&&entry.path().extension()==L".png")deleted.insert(entry.path().filename().u8string());}auto previous=readOrder(),next=previous;next.erase(std::remove_if(next.begin(),next.end(),[&](auto& value){return deleted.count(value);}),next.end());writeOrder(next);try{std::filesystem::remove_all(target);}catch(...){writeOrder(previous);throw;}}

}
